{
    "task_type": "mixed",
    "steps": [
        {
            "id": 1,
            "action": "Get current UTC date",
            "needs": "time"
        },
        {
            "id": 2,
            "action": "Create Hello World website files (index.html, style.css, script.js) in current folder and list them",
